// <auto-generated/>
// Added to test projects by TUnit.Core.props so it compiles ahead of the project's own files.
//
// The C# compiler writes namespaces to the assembly in reverse order of their first declaration.
// Source-generated trees are always added after the project's files, so without this declaration
// the TUnit.Generated types (large static constructors registering every test) are written at the
// very start of the assembly. Antivirus scanners such as Microsoft Defender analyse code at the
// start of an assembly far more expensively, which added seconds to every build and first test run
// of large test projects on Windows. Declaring the namespace first moves the generated types to the
// end of the assembly instead.
namespace TUnit.Generated
{
}
